<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('customers.view');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM customers WHERE id=:id');$st->execute([':id'=>$id]);$c=$st->fetch();if(!$c){flash('error','Customer not found.');redirect('customers/index');}$salesSt=db()->prepare('SELECT id,sale_no,sale_date,total_amount,amount_paid,balance_due,payment_status,status FROM sales WHERE customer_id=:id ORDER BY id DESC LIMIT 15');$salesSt->execute([':id'=>$id]);$sales=$salesSt->fetchAll();$ledgerSt=db()->prepare('SELECT * FROM customer_ledger WHERE customer_id=:id ORDER BY id DESC LIMIT 15');$ledgerSt->execute([':id'=>$id]);$ledger=$ledgerSt->fetchAll();$pageTitle=$c['name'];$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('customers/index'))?>">← Customers</a><h2><?=e($c['name'])?></h2><p><?=e($c['phone']?:$c['email']?:'Customer account')?></p></div><div class="toolbar-actions"><?php if(user_can('credit.record_payment')&&(float)$c['account_balance']>0):?><a class="button button--secondary" href="<?=e(app_url('credit/payment?customer='.$id))?>">Record debt payment</a><?php endif;?><?php if(user_can('customers.update')):?><a class="button button--primary" href="<?=e(app_url('customers/edit?id='.$id))?>">Edit customer</a><?php endif;?></div></div>
<section class="mini-metric-grid"><article class="mini-metric"><span>Outstanding balance</span><strong><?=e(money($c['account_balance']))?></strong></article><article class="mini-metric"><span>Credit limit</span><strong><?=e(money($c['credit_limit']))?></strong></article><article class="mini-metric"><span>Available credit</span><strong><?=e(money(max(0,(float)$c['credit_limit']-(float)$c['account_balance'])))?></strong></article><article class="mini-metric"><span>Status</span><strong class="metric-text"><?=e(ucfirst($c['status']))?></strong></article></section>
<section class="detail-two-column section-gap"><article class="panel-card detail-card"><div class="panel-card__header"><h3>Customer details</h3></div><dl class="detail-list"><div><dt>Phone</dt><dd><?=e($c['phone']?:'—')?></dd></div><div><dt>Email</dt><dd><?=e($c['email']?:'—')?></dd></div><div><dt>Address</dt><dd><?=e($c['address']?:'—')?></dd></div><div><dt>Notes</dt><dd><?=e($c['notes']?:'—')?></dd></div></dl></article><article class="panel-card"><div class="panel-card__header panel-card__header--row"><h3>Credit ledger</h3><a class="table-action" href="<?=e(app_url('credit/statement?customer='.$id))?>">Full statement</a></div><div class="simple-list"><?php if(!$ledger):?><div class="empty-state compact"><strong>No credit activity</strong></div><?php else:foreach($ledger as$l):?><div class="simple-list__row"><div><strong><?=e(ucwords(str_replace('_',' ',$l['entry_type'])))?></strong><span><?=e(format_datetime($l['entry_date']))?> · <?=e($l['reference_no']?:'—')?></span></div><b><?=e(money($l['balance_after']))?></b></div><?php endforeach;endif;?></div></article></section>
<section class="panel-card table-panel section-gap"><div class="panel-card__header"><h3>Sales history</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Sale</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php if(!$sales):?><tr><td colspan="6"><div class="empty-state compact"><strong>No sales yet</strong></div></td></tr><?php else:foreach($sales as$s):?><tr><td><a class="table-action" href="<?=e(app_url('sales/view?id='.(int)$s['id']))?>"><?=e($s['sale_no'])?></a></td><td><?=e(format_datetime($s['sale_date']))?></td><td><?=e(money($s['total_amount']))?></td><td><?=e(money($s['amount_paid']))?></td><td><?=e(money($s['balance_due']))?></td><td><?=e(ucfirst($s['status']))?> / <?=e(ucfirst($s['payment_status']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
</main></div><?php require BASE_PATH.'/includes/footer.php';?>
